  "btn11a_4_3__a": "沿著連結之道前進",
  "btn11a_4_3__b": "沿著可能性之道前進",
  "btn11a_5_1__a": "撿起藤蔓",
  "btn11a_5_2__a": "沿著可能性之道前進",
  "btn11a_5_2__b": "沿著連結之道前進",
